import React from 'react';
import { Composition, registerRoot } from 'remotion';
import { PhonePitch, phonePitchDefaults, phonePitchSchema, W as PPW, H as PPH, FPS as PPFPS, DURATION as PPD } from './scenes/phone-pitch.js';

registerRoot(() => (
  <>
    <Composition id="PhonePitch" component={PhonePitch} schema={phonePitchSchema} defaultProps={phonePitchDefaults}
      durationInFrames={PPD} fps={PPFPS} width={PPW} height={PPH} />
  </>
));

// Our own device drawings: a phone and a laptop, flat, in their own units. One light for everything: a soft key from the
// top left, so edges catch light on the top and left, the glass has a diagonal sheen and shadows fall down and right.
// Nothing here is a real product: no logos, no notch shapes copied from a brand, no wordmarks.

import React from 'react';
import { Layer, Rect, Path, Ellipse, linearGradient, radialGradient } from '@kinetographdev/core';
import { clipRR, rr } from './lib.js';

// ---- phone -----------------------------------------------------------------------------------------------------

export const PW = 390;
export const PH = 800;
const BEZEL = 11;
export const SW = PW - 2 * BEZEL; // 368
export const SH = PH - 2 * BEZEL; // 778
export const SR = 46;

export interface PhoneProps {
  id: string;
  /** The screen content, drawn in a 368 x 778 box. */
  children?: React.ReactNode;
  /** Frame colour. */
  frame?: string;
  /** 0..1: how strongly the glass sheen shows. Slide it with `sheenAt` as the phone turns. */
  sheen?: number;
  /** -1..1: where the sheen band sits across the glass. */
  sheenAt?: number;
  /** The home bar colour: light on dark screens, dark on light. */
  bar?: string;
  /** Dim the screen (a phone not yet woken). 0..1. */
  dim?: number;
}

/** A phone at its resting size, top left at the origin. */
export const Phone: React.FC<PhoneProps> = ({ id, children, frame = '#26272b', sheen = 1, sheenAt = 0, bar = '#ffffff', dim = 0 }) => (
  <Layer id={id}>
    {/* side keys, behind the body so only the edge shows */}
    <Rect id={`${id}-k1`} x={-3} y={170} width={5} height={52} radius={2} fill={frame} />
    <Rect id={`${id}-k2`} x={-3} y={240} width={5} height={52} radius={2} fill={frame} />
    <Rect id={`${id}-k3`} x={PW - 2} y={226} width={5} height={84} radius={2} fill={frame} />
    {/* body: the frame colour with a diagonal light and a hairline highlight */}
    <Rect id={`${id}-body`} width={PW} height={PH} radius={58} fill={frame} />
    <Rect
      id={`${id}-light`}
      width={PW}
      height={PH}
      radius={58}
      fill={linearGradient([[0, '#ffffff55'], [0.28, '#ffffff10'], [0.6, '#00000000'], [1, '#00000066']], { angle: 135 })}
    />
    <Rect id={`${id}-edge`} width={PW} height={PH} radius={58} stroke={{ color: '#ffffff30', width: 1.5 }} />
    {/* black glass bezel and the screen */}
    <Rect id={`${id}-bezel`} x={6} y={6} width={PW - 12} height={PH - 12} radius={53} fill="#050506" />
    <Layer id={`${id}-screen`} x={BEZEL} y={BEZEL} clip={clipRR(SW, SH, SR)}>
      <Rect id={`${id}-screenbase`} width={SW} height={SH} fill="#000" />
      {children}
      {dim > 0 ? <Rect id={`${id}-dim`} width={SW} height={SH} fill="#000" opacity={dim} /> : null}
      <Rect
        id={`${id}-sheen`}
        x={-SW * 0.2 + sheenAt * SW * 0.5}
        y={-SH * 0.1}
        width={SW * 0.9}
        height={SH * 1.2}
        rotation={14}
        opacity={0.1 * sheen}
        fill={linearGradient([[0, '#ffffff00'], [0.5, '#ffffff'], [1, '#ffffff00']], { angle: 90 })}
      />
      <Rect id={`${id}-bar`} x={(SW - 124) / 2} y={SH - 16} width={124} height={5} radius={2.5} fill={bar} opacity={0.85} />
    </Layer>
    <Rect id={`${id}-island`} x={(PW - 112) / 2} y={24} width={112} height={32} radius={16} fill="#000" />
    <Ellipse id={`${id}-lens`} x={(PW + 112) / 2 - 26} y={33} width={14} height={14} fill={radialGradient(['#27304a', '#0b0c12'])} />
  </Layer>
);

// ---- laptop ----------------------------------------------------------------------------------------------------

export const LW = 1120;
export const LH = 700; // lid height
export const LBEZEL = 14;
export const LSW = LW - 2 * LBEZEL; // 1092
export const LSH = LH - 2 * LBEZEL - 4; // screen area height
export const BASE_D = 700; // base depth

export interface LidProps {
  id: string;
  children?: React.ReactNode;
  /** The lid's outer colour. */
  shell?: string;
  /** which face to draw: the screen (inside) or the cover (outside) */
  face: 'screen' | 'cover';
}

/** The lid, drawn flat: top left at the origin. The screen face is LW x LH; the cover is the same box mirrored by the caller. */
export const Lid: React.FC<LidProps> = ({ id, children, shell = '#c9ccd2', face }) =>
  face === 'cover' ? (
    <Layer id={id}>
      <Rect id={`${id}-shell`} width={LW} height={LH} radius={26} fill={linearGradient([shell, '#9fa3ab'], { angle: 160 })} />
      <Rect id={`${id}-spec`} width={LW} height={LH} radius={26} fill={linearGradient([[0, '#ffffff66'], [0.4, '#ffffff00'], [1, '#00000033']], { angle: 135 })} />
      {/* a small centred mark: a plain circle, ours */}
      <Ellipse id={`${id}-mark`} x={LW / 2 - 26} y={LH / 2 - 26} width={52} height={52} stroke={{ color: '#ffffff80', width: 3 }} />
    </Layer>
  ) : (
    <Layer id={id}>
      <Rect id={`${id}-shell`} width={LW} height={LH} radius={26} fill={linearGradient([shell, '#8b8f97'], { angle: 160 })} />
      <Rect id={`${id}-edge`} width={LW} height={LH} radius={26} stroke={{ color: '#ffffff40', width: 1.5 }} />
      <Rect id={`${id}-bezel`} x={7} y={7} width={LW - 14} height={LH - 14} radius={20} fill="#050506" />
      <Layer id={`${id}-screen`} x={LBEZEL} y={LBEZEL + 2} clip={clipRR(LSW, LSH, 8)}>
        <Rect id={`${id}-screenbase`} width={LSW} height={LSH} fill="#000" />
        {children}
        <Rect
          id={`${id}-sheen`}
          x={LSW * 0.1}
          y={-LSH * 0.2}
          width={LSW * 0.5}
          height={LSH * 1.5}
          rotation={20}
          opacity={0.07}
          fill={linearGradient([[0, '#ffffff00'], [0.5, '#ffffff'], [1, '#ffffff00']], { angle: 90 })}
        />
      </Layer>
      <Ellipse id={`${id}-cam`} x={LW / 2 - 3} y={5} width={6} height={6} fill="#14161c" />
    </Layer>
  );

/** The base seen from above, drawn flat: LW wide, BASE_D deep, back edge at the top. Keyboard, trackpad, a light falloff. */
export const Base: React.FC<{ id: string; shell?: string }> = ({ id, shell = '#c9ccd2' }) => {
  const keys: React.ReactNode[] = [];
  const rows = 5;
  const kw = 62;
  const gap = 10;
  const cols = 14;
  const x0 = (LW - (cols * kw + (cols - 1) * gap)) / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      keys.push(<Rect key={`${r}-${c}`} id={`${id}-key-${r}-${c}`} x={x0 + c * (kw + gap)} y={70 + r * (kw * 0.86 + gap)} width={kw} height={kw * 0.86} radius={9} fill="#1c1d22" />);
    }
  }
  return (
    <Layer id={id}>
      <Rect id={`${id}-deck`} width={LW} height={BASE_D} radius={30} fill={linearGradient([shell, '#aeb2ba'], { angle: 180 })} />
      <Rect id={`${id}-well`} x={x0 - 22} y={46} width={cols * kw + (cols - 1) * gap + 44} height={rows * (kw * 0.86 + gap) + 40} radius={16} fill="#101115" />
      {keys}
      <Rect id={`${id}-pad`} x={LW / 2 - 200} y={BASE_D - 215} width={400} height={170} radius={14} fill="#00000014" stroke={{ color: '#00000026', width: 2 }} />
      <Rect id={`${id}-fall`} width={LW} height={BASE_D} radius={30} fill={linearGradient([[0, '#00000040'], [0.18, '#00000000'], [0.8, '#ffffff00'], [1, '#ffffff40']], { angle: 180 })} />
      <Rect id={`${id}-dent`} x={LW / 2 - 90} y={BASE_D - 14} width={180} height={14} radius={7} fill="#00000022" />
    </Layer>
  );
};

export { rr };

// Small timing and drawing helpers shared by the showcase components. Every function is pure in the frame number.

import { Easing, interpolate } from 'remotion';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

/** slow in, slow out: the default for anything that travels */
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
/** fast start, long settle: things arriving */
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
/** slow start, fast end: things leaving at speed */
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);

/** from `from` at frame a to `to` at frame b, held outside */
export const ramp = (f: number, a: number, b: number, from: number, to: number, easing: (t: number) => number = ease) =>
  interpolate(f, [a, b], [from, to], { ...clamp, easing });

/** 0 to 1 over [a, b], eased */
export const prog = (f: number, a: number, b: number, easing: (t: number) => number = ease) => ramp(f, a, b, 0, 1, easing);

/** Keyframes [[frame, value], ...] with one easing on every segment. */
export function keys(f: number, k: [number, number][], easing: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * easing((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

/** A damped spring from 0 at frame `a` to 1: overshoots, then settles. `bounce` 0.2 is gentle, 0.5 lively. */
export function spring(f: number, a: number, dur = 30, bounce = 0.25): number {
  const t = (f - a) / dur;
  if (t <= 0) return 0;
  if (t >= 1.6) return 1;
  const damp = 5.5;
  const w = Math.PI * 2 * (0.6 + bounce * 1.4);
  return 1 - Math.exp(-damp * t) * Math.cos(w * t);
}

/** Path data for a w x h rounded rectangle at the origin. */
export const rr = (w: number, h: number, r: number): string => {
  r = Math.min(r, w / 2, h / 2);
  return `M${r} 0H${w - r}A${r} ${r} 0 0 1 ${w} ${r}V${h - r}A${r} ${r} 0 0 1 ${w - r} ${h}H${r}A${r} ${r} 0 0 1 0 ${h - r}V${r}A${r} ${r} 0 0 1 ${r} 0Z`;
};

export const clipRR = (w: number, h: number, r: number) => ({ kind: 'path' as const, d: rr(w, h, r) });

/** Registers a Google Fonts family and returns the name to put in `font`. */
export const useFamily = (family: string, weights: string[] = ['400', '500', '600'], italic = false): string => {
  const mod = makeGoogleFont(family.replace(/\s+/g, ''));
  if (italic) mod.loadFont('italic', { weights });
  return mod.loadFont('normal', { weights }).fontFamily;
};

/** A point on a circle, for arcs: angle in degrees from straight up, clockwise. */
export const onArc = (cx: number, cy: number, r: number, deg: number) => ({
  x: cx + r * Math.sin((deg * Math.PI) / 180),
  y: cy - r * Math.cos((deg * Math.PI) / 180),
});

/** A smooth hash noise in [-1, 1] of a time and a seed: slow handheld drift without Math.random. */
export const drift = (f: number, seed: number, speed = 0.02): number => {
  const t = f * speed;
  const i = Math.floor(t);
  const h = (n: number) => {
    const s = Math.sin((n + seed * 97.13) * 127.1) * 43758.5453;
    return (s - Math.floor(s)) * 2 - 1;
  };
  const u = t - i;
  const s = u * u * (3 - 2 * u);
  return h(i) * (1 - s) + h(i + 1) * s;
};

// Phone Pitch, scene phone-pitch: a phone is put down from the right, a two-line headline says itself a word at a
// time beside it, and on the glass a message thread plays out with each reply landing on its own beat. Then the headline
// leaves, the camera lifts and closes on the phone until the screen is the shot, and the thread keeps going: a typing
// indicator, a last reply, a hold.
//
// Principles: anticipation (nothing moves until the words are in), slow in and out (the camera's lift is one eased move),
// follow through (words overshoot a little right and settle), overlap (the headline leaves as the camera starts, not before),
// staging (the phone is the hero, the type is the margin note), timing (messages land at human intervals, the typing dots
// buy the last reply a beat).

import React from 'react';
import { z } from 'zod';
import { Ellipse, Layer, Path, Rect, Text, grain } from '@kinetographdev/core';
import { Easing, useCurrentFrame } from 'remotion';
import { PH, PW, Phone } from './devices.js';
import { easeIn, easeOut, prog, ramp, ease, rr, useFamily } from './lib.js';

export const W = 1920;
export const H = 1080;
export const FPS = 60;
export const DURATION = 470;
export { PW as PW_, PH as PH_ };

const hex = z.string().describe('A CSS colour.');

export const phonePitchSchema = z.object({
  headline: z.array(z.string()).length(2).describe('The two headline lines, set a word at a time.'),
  contact: z.string().describe('The name under the avatar in the thread header.'),
  thread: z
    .array(
      z.object({
        from: z.enum(['me', 'them']).describe('me is the blue right-hand bubble, them the grey left-hand one.'),
        text: z.string().describe('Message text. A newline forces a line break.'),
        at: z.number().int().min(0).describe('Frame the message lands on (60 fps). 0 means already there.'),
      }),
    )
    .describe('The conversation, in order.'),
  typing: z.object({ from: z.number().int(), to: z.number().int() }).describe('The frames the typing dots show for, before the last message.'),
  headlineFont: z.string().describe('Google Fonts family of the headline.'),
  uiFont: z.string().describe('Google Fonts family of the thread.'),
  ground: hex.describe('The ground behind the phone.'),
  ink: hex.describe('Headline colour.'),
  bubble: hex.describe('The blue of your own bubbles.'),
  frame: hex.describe('Phone frame colour.'),
  flip: z.boolean().describe('Mirror the layout: phone on the left, headline on the right.'),
  speed: z.number().min(0.5).max(2).describe('Playback speed of the move.'),
  grain: z.number().min(0).max(0.2).describe('Film grain over the whole frame.'),
});
export type PhonePitchProps = z.infer<typeof phonePitchSchema>;

export const phonePitchDefaults: PhonePitchProps = {
  headline: ['Let Orbit', 'handle it'],
  contact: 'Orbit',
  thread: [
    { from: 'me', text: 'i need a launch video by friday', at: 0 },
    { from: 'me', text: 'how am i looking', at: 0 },
    { from: 'them', text: 'i gotchu', at: 56 },
    { from: 'them', text: 'cut it from your library — script,\npacing, captions', at: 100 },
    { from: 'me', text: 'the deck still needs a hero shot', at: 190 },
    { from: 'me', text: "and i don't wanna re-record the\nvo", at: 270 },
    { from: 'them', text: 'say less — first cut lands in your\ninbox tonight', at: 404 },
  ],
  typing: { from: 368, to: 402 },
  headlineFont: 'Geist',
  uiFont: 'Inter',
  ground: '#effafe',
  ink: '#0f1a24',
  bubble: '#3f8cf7',
  frame: '#1d1e22',
  flip: false,
  speed: 1,
  grain: 0,
};

// layout of the thread, in screen units (the glass is 368 x 778)
const SIDE = 25;
const GAP = 16;
const HEAD = [185]; // top of the first bubble
const heightOf = (t: string) => (t.split('\n').length > 1 ? 64 : 36);

const Bubble: React.FC<{ id: string; y: number; from: 'me' | 'them'; text: string; color: string; font: string; t: number }> = ({ id, y, from, text, color, font, t }) => {
  const lines = text.split('\n');
  const longest = Math.max(...lines.map((l) => [...l].length));
  const w = Math.min(250, longest * 7.05 + 30);
  const h = heightOf(text);
  const me = from === 'me';
  const x = me ? 368 - SIDE - w : SIDE - 8;
  const pop = easeOut(t);
  return (
    <Layer id={id} x={x + (me ? w : 0)} y={y + h / 2} anchorX={me ? w : 0} anchorY={h / 2} scale={0.82 + 0.18 * pop} opacity={Math.min(1, t * 3)}>
      <Layer id={`${id}-in`} y={-h / 2 + (1 - pop) * 14}>
        <Rect id={`${id}-bg`} width={w} height={h} radius={18} fill={me ? color : '#e9e9eb'} />
        <Rect id={`${id}-tail`} x={me ? w - 14 : 0} y={h - 14} width={14} height={14} radius={me ? 0 : 0} fill={me ? color : '#e9e9eb'} />
        <Text id={`${id}-tx`} font={font} weight={400} size={14} color={me ? '#ffffff' : '#101114'} x={me ? 15 : 15} y={h === 36 ? 9 : 10} maxWidth={w} lineHeight={1.25}>
          {text}
        </Text>
      </Layer>
    </Layer>
  );
};

const Dots: React.FC<{ f: number; y: number }> = ({ f, y }) => (
  <Layer id="pp-dots" x={SIDE - 8} y={y} opacity={prog(f, 0, 6)}>
    <Rect id="pp-dots-bg" width={64} height={34} radius={17} fill="#e9e9eb" />
    {[0, 1, 2].map((i) => (
      <Ellipse key={i} id={`pp-dot${i}`} x={17 + i * 14} y={13} width={8} height={8} fill={i === Math.floor(f / 14) % 3 ? '#6e6f75' : '#b9bac0'} />
    ))}
  </Layer>
);

export const PhonePitch: React.FC<PhonePitchProps> = (p) => {
  const frame = useCurrentFrame();
  const f = frame * p.speed;
  const head = useFamily(p.headlineFont, ['500', '600', '700']);
  const ui = useFamily(p.uiFont, ['400', '500', '600']);
  const dir = p.flip ? -1 : 1;

  // the phone: put down from the side (keeps 87.7% of the remaining distance per frame), then the lift and close-in
  const land = 175 * Math.pow(0.877, frame);
  const lift = prog(f, 186, 250, Easing.bezier(0.5, 0, 0.3, 1));
  const zoom = 1 + 0.38 * lift;
  const ps = 2.03 * zoom;
  const cx = W / 2 + dir * (420 * (1 - lift) + land);
  const top = 66 + (-470 - 66) * lift;

  // thread layout and scroll
  let yy = HEAD[0];
  const placed = p.thread.map((m) => {
    const y = yy;
    yy += heightOf(m.text) + GAP;
    return { ...m, y };
  });
  const scroll = ramp(f, 262, 288, 0, 60) + ramp(f, 366, 392, 0, 90) + ramp(f, 400, 428, 0, 22);
  const dotsY = (placed[placed.length - 1]?.y ?? 0);

  // headline: a word at a time, a touch right, small and light, settling; then it leaves with the lift
  const words: { w: string; line: number; at: number }[] = [];
  const starts = [28, 42, 49, 56];
  let wi = 0;
  p.headline.forEach((l, li) => l.split(' ').forEach((w) => words.push({ w, line: li, at: starts[Math.min(wi++, starts.length - 1)] })));
  const exit = easeIn(prog(f, 164, 204));
  const hx = (p.flip ? W - 105 : 105) - dir * 330 * exit;
  const sizes = [84, 100];
  const lineH = [112, 112];

  const lineText = (li: number) => {
    // place words by an estimated advance so each can arrive on its own beat
    const ws = words.filter((x) => x.line === li);
    let x = 0;
    return ws.map((x0) => {
      const adv = [...x0.w].length * sizes[li] * (li === 0 ? 0.53 : 0.56) + sizes[li] * 0.3;
      const out = { ...x0, x };
      x += adv;
      return out;
    });
  };

  return (
    <Layer id="pp-root" effects={p.grain > 0 ? [grain(p.grain, { seed: 3, size: 1.3 })] : undefined}>
      <Rect id="pp-ground" width={W} height={H} fill={p.ground} />
      <Layer id="pp-head" x={hx} y={0} opacity={1 - exit}>
        {[0, 1].map((li) => (
          <Layer id={`pp-line${li}`} key={li} y={H / 2 - 100}>
            {lineText(li).map((wd, k) => {
              const t = easeOut(prog(f, wd.at, wd.at + 14));
              return (
                <Text
                  key={k}
                  id={`pp-w${li}-${k}`}
                  font={head}
                  weight={li === 0 ? 500 : 700}
                  size={sizes[li]}
                  color={li === 0 ? '#223340' : p.ink}
                  x={(p.flip ? -520 : 0) + wd.x + (1 - t) * 26}
                  y={li * 112}
                  lineHeight={1}
                  opacity={t}
                >
                  {wd.w}
                </Text>
              );
            })}
          </Layer>
        ))}
      </Layer>
      <Layer id="pp-phone" x={cx - (PW * ps) / 2} y={top} scale={ps}>
        <Phone id="pp-ph" frame={p.frame} bar="#111">
          <Rect id="pp-screen-bg" width={368} height={778} fill="#ffffff" />
          {/* status bar */}
          <Text id="pp-time" font={ui} weight={600} size={16} color="#0a0a0a" x={32} y={22} lineHeight={1}>9:41</Text>
          <Rect id="pp-sig" x={285} y={28} width={4} height={8} radius={1} fill="#0a0a0a" />
          <Rect id="pp-sig2" x={291} y={25} width={4} height={11} radius={1} fill="#0a0a0a" />
          <Rect id="pp-sig3" x={297} y={22} width={4} height={14} radius={1} fill="#0a0a0a" />
          <Rect id="pp-bat" x={316} y={24} width={26} height={13} radius={4} fill="#0a0a0a" />
          {/* header */}
          <Layer id="pp-hdr">
            <Ellipse id="pp-back" x={24} y={63} width={38} height={38} fill="#f0f0f2" />
            <Path id="pp-chev" d="M49 73 L42 82 L49 91" x={0} y={0} stroke={{ color: '#2a2a2e', width: 2.2, cap: 'round', join: 'round' } as never} />
            <Ellipse id="pp-av" x={161} y={60} width={46} height={46} fill="#1b2943" />
            <Text id="pp-avl" font={ui} weight={600} size={20} color="#ffffff" align="center" x={161} y={72} maxWidth={46} lineHeight={1}>{p.contact.slice(0, 1)}</Text>
            <Ellipse id="pp-vid" x={306} y={63} width={38} height={38} fill="#f0f0f2" />
            <Rect id="pp-vid1" x={316} y={76} width={15} height={12} radius={3} fill="#2a2a2e" />
            <Rect id="pp-pill" x={141} y={118} width={86} height={24} radius={12} fill="#f0f0f2" />
            <Text id="pp-name" font={ui} weight={500} size={12} color="#1c1c20" align="center" x={141} y={124} maxWidth={86} lineHeight={1}>{`${p.contact} ›`}</Text>
          </Layer>
          {/* thread */}
          <Layer id="pp-thread" y={-scroll} clip={undefined}>
            {placed.map((m, i) => (
              <Bubble key={i} id={`pp-m${i}`} y={m.y} from={m.from} text={m.text} color={p.bubble} font={ui} t={m.at === 0 ? 1 : prog(f, m.at, m.at + 16, easeOut)} />
            ))}
            {f >= p.typing.from && f < p.typing.to ? <Dots f={f - p.typing.from} y={dotsY} /> : null}
          </Layer>
          {/* a soft cover so messages scroll out under the header */}
          <Rect id="pp-hdr-cover" width={368} height={150} fill="#ffffff" opacity={0} />
        </Phone>
      </Layer>
